import test from 'node:test';
import assert from 'node:assert/strict';
import { catalog, state, play, endTurn, startTurn, cardText } from './model.mjs';
const hit = (id, upgraded = false, extra = {}) => play(state({ hand: [id], ...extra }), { index: 0, upgraded }).state;
// Independent, handwritten oracles, not snapshots generated by current implementation.
for (const up of [false, true]) {
  test(`basic cost, damage, block and zones upgraded=${up}`, () => {
    const a = hit('x01', up); assert.equal(a.energy, 2); assert.equal(a.enemies[0].hp, up ? 21 : 24); assert.deepEqual(a.discard, ['x01']);
    assert.equal(hit('x02', up).block, up ? 8 : 5);
    assert.equal(hit('x03', up).enemies[0].hp, up ? 18 : 21);
    const g = hit('x07', up); assert.equal(g.enemies[0].hp, up ? 23 : 25); assert.equal(g.block, up ? 7 : 5);
  });
  test(`mask and plunge independent expected values upgraded=${up}`, () => {
    let s = state({ hand: ['x04','x05'], enemies: [{hp:30,block:3},{hp:8,block:0}] });
    s = play(s, {index:0,upgraded:up}).state;
    assert.equal(s.hp,68); assert.equal(s.mask,up?3:2); assert.equal(s.energy,2);
    s = play(s,{index:0,upgraded:up}).state;
    assert.equal(s.enemies[0].hp,up?20:23); assert.equal(s.enemies[1].hp,0); assert.equal(s.energy,1);
    const ordinary=hit('x05',up,{enemies:[{hp:30,block:0},{hp:30,block:0}]});
    assert.equal(ordinary.enemies[0].hp,up?21:24); assert.equal(ordinary.enemies[1].hp,30);
  });
  test(`draw cap, exhaust and exit upgraded=${up}`,()=>{
    const d=hit('x08',up,{draw:['x01','x02','x03','x04']});assert.equal(d.hand.length,up?3:2);
    let s=state({hand:['x06']});s.mask=2;s=play(s,{index:0,upgraded:up}).state;
    assert.equal(s.mask,0);assert.equal(s.block,up?6:4);assert.deepEqual(s.exhaust,['x06']);assert.equal(s.energy,3);
    const full=hit('x08',up,{hand:['x08',...Array(9).fill('x01')],draw:['x02','x03','x04']});
    assert.equal(full.hand.length,10); assert.deepEqual(full.draw,['x03','x04']);
  });
}
test('all rejection paths preserve exact input and clone result',()=>{
  for(const [s,request] of [
    [state({hand:['x01']}),{index:0,cancel:true}],
    [state({hand:['x01'],energy:0}),{index:0}],
    [state({hand:['x04'],hp:2}),{index:0}],
    [state({hand:['x01']}),{index:2}],
    [state({hand:['x01']}),{index:0,target:-1}],
    [state({hand:['unknown']}),{index:0}],
    [state({hand:['x01']}),{index:0,upgraded:'false'}],
    [state({hand:['x01'],hp:0}),{index:0}],
    [state({hand:['x01'],enemies:[{hp:0,block:0}]}),{index:0}],
  ]) {const before=structuredClone(s);const r=play(s,request);assert.equal(r.ok,false);assert.deepEqual(r.state,before);assert.deepEqual(s,before);assert.notEqual(r.state,s);}
});
test('end turn is idempotent, costs bypass block and can kill',()=>{
  let s=state({hp:2,hand:['x01']});s.mask=2;s.block=100;
  s=endTurn(s);assert.equal(s.hp,0);assert.equal(s.mask,1);assert.equal(s.block,100);assert.deepEqual(s.discard,['x01']);
  assert.deepEqual(endTurn(s),s);assert.deepEqual(startTurn(s),s);
});
test('duration and refresh are bounded, victory costs no further life',()=>{
  let s=state({hand:['x04','x04']});s=play(s,{index:0}).state;s=play(s,{index:0}).state;assert.equal(s.mask,2);assert.equal(s.hp,66);
  for(let i=0;i<100;i++)s=startTurn(endTurn(s));assert.equal(s.hp,62);assert.equal(s.mask,0);
  s.enemies[0].hp=0;s.mask=2;assert.deepEqual(endTurn(s),s);
});
test('card order is meaningful without retroactive bonus',()=>{
  const s=state({hand:['x01','x04']});
  const normal=play(play(s,{index:0}).state,{index:0}).state;
  const firstMask=play(play(s,{index:1}).state,{index:0}).state;
  assert.equal(normal.enemies[0].hp,24);assert.equal(firstMask.enemies[0].hp,20);
});
test('low-life choice differs from burst choice',()=>{
  let s=state({hp:3,hand:['x04','x05','x06']});s=play(s,{index:0}).state;assert.equal(s.hp,1);
  assert.equal(endTurn(s).hp,0);const leave=play(s,{index:1}).state;assert.equal(endTurn(leave).hp,1);
});
test('one-turn resource loop is finite: no energy generation, each card leaves hand',()=>{
  let s=state({hand:Array(10).fill('x06')});for(let i=0;i<10;i++)s=play(s,{index:0}).state;
  assert.equal(s.hand.length,0);assert.equal(s.exhaust.length,10);assert.equal(play(s,{index:0}).ok,false);
});
test('turn guards prevent duplicate start, draws are not fabricated without deck',()=>{
  let s=state({hand:['x01'],draw:['x02']});assert.deepEqual(startTurn(s),s);
  s=endTurn(s);assert.equal(play(s,{index:0}).reason,'phase');s=startTurn(s);assert.deepEqual(s.hand,['x02']);assert.equal(s.energy,3);assert.equal(s.block,0);
  assert.deepEqual(startTurn(s),s);
});
test('versioned cards all have both forms and HOLD names, texts derive each form',()=>{
  assert.equal(new Set(catalog.cards.map(c=>c.id)).size,38);
  for(const c of catalog.cards){assert.equal(c.name,`待命名·${c.id}`);assert.equal(c.naming.humanApproved,false);assert.ok(c.base.length&&c.upgrade.length);for(const up of [false,true])assert.ok(cardText(c,up).startsWith(`${c.cost}费。`));}
  assert.match(cardText(catalog.cards[4],true),/所有敌人造成13点/);
});
test('post-payment unknown effect rolls back all prior effects',()=>{
  const card=catalog.cards[0];const beforeEffects=structuredClone(card.base);
  try {card.base.push({op:'unknown',value:1});const s=state({hand:['x01']});const r=play(s,{index:0});assert.equal(r.reason,'effect');assert.deepEqual(r.state,s);assert.equal(s.energy,3);assert.equal(s.enemies[0].hp,30);}
  finally {card.base=beforeEffects;}
});
test('duration one expires; weaker refresh never shortens; lethal thresholds exact',()=>{
  let s=state({hand:['x04']});s.mask=3;s=play(s,{index:0}).state;assert.equal(s.mask,3);
  s.mask=1;s=endTurn(s);assert.equal(s.mask,0);assert.equal(s.hp,66);
  for(const hp of [9,10,11]){let q=state({hand:['x01'],enemies:[{hp,block:0}]});q.mask=1;q=play(q,{index:0}).state;assert.equal(q.enemies[0].hp,Math.max(0,hp-10));}
});
test('upgrade extra duration is documented negative life outcome, not free benefit',()=>{
  for(const up of [false,true]){let s=state({hp:8,hand:['x04']});s=play(s,{index:0,upgraded:up}).state;
    for(let i=0;i<3;i++)s=startTurn(endTurn(s));assert.equal(s.hp,up?0:2);}
});
test('card text states structured mask bonus and life loss for each form',()=>{
  for(const up of [false,true]){const text=cardText(catalog.cards[3],up);assert.match(text,/攻击\+4/);assert.match(text,/先失去2生命/);assert.match(text,up?/状态3回合/:/状态2回合/);}
});
test('invalid numeric and structural states fail atomically including NaN exploits',()=>{
  const invalid=[...['hp','energy','block','mask'].flatMap(key=>[NaN,Infinity,-1,1.5].map(value=>s=>s[key]=value)),s=>s.mask=4,s=>s.hp=71,s=>s.enemies[0].hp=NaN,s=>s.enemies[0].block=-1,s=>s.hand=Array(11).fill('x01'),s=>s.phase='finished',s=>s.turn=0,s=>s.relicUsed='false'];
  for(const change of invalid){const s=state({hand:['x04']});change(s);const before=structuredClone(s);const r=play(s,{index:0});assert.equal(r.ok,false);assert.equal(r.reason,'state');assert.deepEqual(r.state,before);assert.deepEqual(s,before);assert.deepEqual(endTurn(s),before);assert.deepEqual(startTurn(s),before);}
});
